"""Expand the PGCP-AI question banks to the requested 600 records.

The additions are deterministic, topic-linked MCQs with four options, answer
rationales, hints and stable IDs. Existing records are never rewritten.
"""
import json, math, random
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
D=ROOT/'data'
files={'core':'questions-core.json','practical':'questions-practical.json','extension':'questions-extension.json'}
rows={k:json.loads((D/v).read_text()) for k,v in files.items()}
original_numbers={q['id']:q['number'] for bank_rows in rows.values() for q in bank_rows}

def make(bank, topic, stem, correct, wrong, explanation, hint, difficulty='medium', typ='concept'):
    # exactly three distractors with distinct, topic-relevant misconception explanations
    assert len(wrong)==3 and len(set([correct]+[x[0] for x in wrong]))==4
    prefix={'core':'CORE','practical':'PRACTICAL','extension':'EXT'}[bank]
    n=len(rows[bank])+1
    qid=f'{prefix}-{n:03d}'
    opts=[correct]+[x[0] for x in wrong]
    rationales=['Correct. '+explanation]+[x[1] for x in wrong]
    # Deterministic, balanced answer positions
    shift=(n*7 + len(topic))%4
    opts=opts[shift:]+opts[:shift]
    rationales=rationales[shift:]+rationales[:shift]
    ans=(4-shift)%4
    rows[bank].append({'id':qid,'number':sum(len(v) for v in rows.values()),'bank':bank,'topicId':topic,'difficulty':difficulty,'type':typ,'question':stem,'options':opts,'correctAnswer':ans,'explanation':explanation,'optionExplanations':rationales,'hint':hint,'referenceId':topic+'-ref'})

