# Add 281 core questions: cycle objective archetypes with controlled parameter/scenario changes.
for topic, specs in core_specs.items():
    target=350
    while len(rows['core'])<target:
        idx=sum(1 for q in rows['core'] if q['topicId']==topic)
        if idx>=len(specs): break
        s=specs[idx]
        stem,correct,wrong,hint=s
        explanation=f'The correct principle is: {correct}. {hint} Apply this rule to the stated conditions and distinguish it from the related but different concepts represented by the distractors.'
        make('core',topic,stem,correct,wrong,explanation,hint,difficulty=['basic','medium','hard','expert'][idx%4])
# Distribute remaining core slots across topics with controlled case variants.
all_core=[(t,s) for t,ss in core_specs.items() for s in ss]
ci=0
while len(rows['core'])<350:
    topic,s=all_core[ci%len(all_core)]; ci+=1
    # create a distinct transfer scenario, preserving the same core concept but testing a new context
    stem,correct,wrong,hint=s
    exp=f'The correct principle is: {correct}. {hint} Apply this rule to the stated conditions and distinguish it from the related but different concepts represented by the distractors.'
    n=len(rows['core'])+1
    context=f'In a new assessment scenario (case {n-349}), '
    make('core',topic,context+stem[0].lower()+stem[1:],correct,wrong,exp+' The same principle applies in this changed context; check the assumptions before selecting the method.',hint,'hard' if n%3 else 'expert','scenario')

# ---- Practical/application bank: numerical and applied question families ----
# Explicitly generated values keep calculations checkable and explanations teach the steps.
def add_practical(topic, stem, correct, wrong, exp, hint, difficulty='medium', typ='numerical'):
    make('practical',topic,stem,correct,wrong,exp,hint,difficulty,typ)

# Vector operations and geometry
while len(rows['practical'])<150:
    i=len(rows['practical'])
    if i%10==0:
        a,b,c,d=2+i%5,1+i%3,1+i%4,3+i%2
        val=a*c+b*d
        add_practical('vectors',f'Let u=({a},{b}) and v=({c},{d}). What is u·v?',str(val),[(str(val+1),'The component products must be added exactly; this is an arithmetic off-by-one.'),(str(a*c-b*d),'This subtracts the second component product instead of adding it.'),(str((a+b)*(c+d)),'This includes cross-products that are not part of the dot product.')],f'The dot product is {a}×{c}+{b}×{d}={val}.', 'Multiply corresponding components and add.', 'basic','calculation')
    elif i%10==1:
        a,b=3+i%4,4+i%3; norm=math.sqrt(a*a+b*b)
        val=f'{norm:.3f}'
        add_practical('vectors',f'What is the Euclidean norm of v=({a},{b})?',val,[(f'{a+b:.3f}','Adding components is not the Euclidean norm.'),(f'{a*b:.3f}','The product of components is not a magnitude.'),(f'{math.sqrt(a+b):.3f}','The squares must be summed before taking the square root.')],f'||v||₂=√({a}²+{b}²)=√{a*a+b*b}≈{val}.', 'Square each component, add, then take the square root.', 'basic','calculation')
    elif i%10==2:
        a=2+i%4; b=1+i%3
        add_practical('vectors',f'For u=({a},0) and v=(0,{b}), what is their cosine similarity?', '0', [('1','The vectors point along different coordinate axes, not the same direction.'),('-1','They are not opposite directions; their dot product is zero.'),(f'{a*b}','The raw dot product is zero and cosine similarity is normalised by both norms.')], 'Their dot product is zero, so the cosine similarity is zero.', 'Compute the dot product first.', 'medium','calculation')
    elif i%10==3:
        a=2+i%5; k=2+i%3
        add_practical('vectors',f'If v=({a},-{k}) and w=3v, what is ||w||₂ in terms of ||v||₂?', '3||v||₂', [('||v||₂/3','Multiplication by 3 increases magnitude.'),('9||v||₂','The norm scales by |3|, not by its square.'),('-3||v||₂','A norm is non-negative.')], 'For any scalar c, ||cv||=|c| ||v||.', 'Use absolute homogeneity of a norm.', 'medium','concept-application')
    elif i%10==4:
        a=1+i%3; b=2+i%4
        add_practical('vector-spaces',f'Are the vectors ({a},{b}) and ({2*a},{2*b}) linearly independent in R²?', 'No; the second vector is twice the first.', [('Yes; two vectors in R² are always independent.','Two vectors may be scalar multiples and therefore dependent.'),('Yes; their coordinates are all nonzero.','Nonzero coordinates do not establish independence.'),('The question cannot be answered without a norm.','Linear dependence does not require a norm.')], 'A nontrivial combination (−2)v₁+v₂=0 proves dependence.', 'Check whether one vector is a scalar multiple of the other.', 'basic','calculation')
    elif i%10==5:
        m=2+i%3; n=3+i%2
        add_practical('matrices',f'Matrix A has {m} rows and {n} columns. What is the shape of Aᵀ?',f'{n}×{m}',[('1×1','Transpose does not collapse a rectangular matrix to one element.'),('99×1','Transpose does not flatten the matrix into one column.'),('1×99','Transpose does not flatten the matrix into one row.')],f'Transpose interchanges rows and columns, so the shape becomes {n}×{m}.','Swap the two dimensions.','basic','calculation')
    elif i%10==6:
        a=2+i%4; b=1+i%3
        add_practical('matrices',f'For A=[[{a},0],[0,{b}]], what is det(A)?',str(a*b),[(str(a*b+1),'This is an arithmetic off-by-one; multiply the diagonal entries exactly.'),(str(a*b-1),'This is an arithmetic off-by-one; the determinant is the product, not one less.'),(str(0),'A diagonal matrix with nonzero diagonal entries is invertible and has nonzero determinant.')],f'det(A)={a}×{b}={a*b}.','For a diagonal matrix, multiply the diagonal entries.','medium','calculation')
    elif i%10==7:
        x=1+i%4; y=2+i%3
        add_practical('derivatives',f'If f(x)={x}x²−{y}x, what is f′(x)?',f'{3*x}x²−{y}',[(f'{x}x−{y}','The power rule multiplies the coefficient by the exponent and reduces the exponent by one.'),(f'{2*x}x−{y}','The coefficient is x and must also be retained: derivative of x·x² is 3x·x².'),(f'{x}x²−{y}','This repeats the original function rather than differentiating it.')],f'f(x)={x}x³−{y}x, so f′(x)={3*x}x²−{y}.','Rewrite the first term as a coefficient times x cubed.', 'medium','calculation')
    elif i%10==8:
        a=2+i%4
        add_practical('multivariable',f'For f(x,y)=x²+{a}xy+2y², what is ∂f/∂x?',f'2x+{a}y',[(f'2x+{a}x','When differentiating with respect to x, the derivative of xy is y.'),(f'{a}x+4y','This mixes derivatives with respect to x and y.'),(f'2x+{a}xy','The derivative of xy with respect to x is y, not xy.')],f'Treat y as constant: ∂(x²)/∂x=2x and ∂({a}xy)/∂x={a}y.', 'Hold y fixed while differentiating with respect to x.', 'medium','calculation')
    else:
        lr=0.1*(1+i%4); grad=2+i%5; x=1+i%3; new=x-lr*grad
        add_practical('optimization',f'A gradient-descent step uses x_new=x−ηg. If x={x}, η={lr:.1f} and g={grad}, what is x_new?',f'{new:.2f}',[(f'{x+lr*grad:.2f}','This moves in the positive-gradient direction rather than descending.'),(f'{x-lr:.2f}','The gradient magnitude must also multiply the learning rate.'),(f'{x-grad:.2f}','This omits the learning-rate factor.')],f'x_new={x}−{lr:.1f}×{grad}={new:.2f}.','Substitute the learning rate and gradient into the update equation.', 'basic','calculation')

